const MOD='ecos-frontera',incidencias=[];
export const PRUEBAS_REALES=[
 {id:'creacion',titulo:'Crear y revisar un personaje',pasos:'En una ficha de prueba importa clase, especie y trasfondo con Plutonium. Completa los avances. La revisión debe detectar elecciones pendientes o repetidas. Aprueba desde el DM y cambia una elección: debe pedir revisión nueva.'},
 {id:'ecos',titulo:'Separar Ecos y Verbe',pasos:'Activa las reglas de Ecos desde la revisión del DM. Comprueba el indicador. Despierta el Verbe por separado y revisa linaje, fuerza, reserva y ramas. Apagar uno no debe modificar el otro.'},
 {id:'uso',titulo:'Aprender y usar una técnica',pasos:'Aprende una técnica de grado 1 en una copia con recursos conocidos. Marca un objetivo válido. Usa la técnica y comprueba un solo gasto, tirada y tarjeta de resolución.'},
 {id:'defensa',titulo:'Defensa antes del choque',pasos:'Con dos hojas despiertas prueba Sustitución frente a un ataque. Después prueba un ataque que siga siendo válido: el choque debe ofrecerse después de las defensas y respetar sus costes.'},
 {id:'area',titulo:'Área con varios objetivos',pasos:'Marca al menos dos defensores y una criatura sin Verbe. Intercepta contra uno: los demás objetivos deben conservar su resolución. Comprueba alcance, plantilla y salvaciones.'},
 {id:'reaccion',titulo:'Choque con reacción gastada',pasos:'Gasta la reacción ordinaria de un defensor. Provoca un choque válido: debe poder pagar su contratécnica sin recibir una acción ofensiva o daño adicional.'},
 {id:'azar',titulo:'Resultados naturales 1 y 20',pasos:'Desde tiradas nativas prueba ventaja y desventaja, varios ataques y una salvación. Solo cuenta el primer d20 válido del turno global. El GM principal aprueba. CA y velocidad deben vencer en su momento.'},
 {id:'ocultas',titulo:'Información y tiradas privadas',pasos:'Conecta un jugador y el DM. Prueba tiradas ocultas y búsquedas. El jugador no debe recibir diarios, páginas o reliquias privadas; las propuestas de d20 deben conservar destinatarios.'},
 {id:'descanso',titulo:'Descansos y deuda',pasos:'Anota Verbe, deuda, presupuesto breve y usos diarios. Completa un Corto y después el Largo correspondiente. Comprueba los límites compartidos y las excepciones descritas, como Sustitución refleja.'},
 {id:'npc',titulo:'Variantes de NPC y reversión',pasos:'Usa un NPC importado con Multiataque o magia. Revisa los avisos. Crea una copia privada y comprueba que el original no cambie. Actualiza una copia de prueba y deshaz su última adaptación.'},
 {id:'sintetico',titulo:'Tokens vinculados y no vinculados',pasos:'Repite un gasto, un efecto breve y su vencimiento en un token vinculado y en uno no vinculado. Los cambios deben afectar a la instancia correcta.'},
 {id:'correccion',titulo:'Corrección de un gasto simple',pasos:'Usa una técnica ordinaria de grado bajo sin efectos de recurso especiales. Desde el DM corrige su gasto antes de otro uso: debe restaurar solo Verbe. Un uso posterior o un poder complejo debe bloquear esa corrección automática.'},
 {id:'reconexion',titulo:'Recargar y reconectar',pasos:'Recarga jugador y DM después de un uso. Comprueba recursos, efectos, permisos y tarjetas. Revisa que el módulo no cobre de nuevo ni duplique una resolución.'},
 {id:'actualizacion',titulo:'Actualizar con respaldo',pasos:'Respalda el mundo de prueba. En la pantalla de inicio de Foundry, Módulos → Buscar actualizaciones y actualiza Ecos. Reabre el mundo y comprueba versión y datos. Conserva el respaldo hasta terminar la revisión.'},
 {id:'sesion',titulo:'Primera escena sin manual',pasos:'Pide a alguien nuevo que cree una ficha de prueba, encuentre una técnica por intención y juegue una escena social y otra de combate. Anota dónde necesitó una explicación externa.'},
 {id:'plantilla35',titulo:'3.5 · Cono que no te alcanza',pasos:'En una escena medida en pies, usa Aliento de brasa con un objetivo delante. El cono debe medir 15 pies, colocarse desde ti y no dañarte. Repite en una escena en metros (15 ft).'},
 {id:'ventaja35',titulo:'3.5 · Ventaja en cada ataque',pasos:'Ataca con un PJ y con un PNJ. Siempre debe abrirse la ventana Normal/Ventaja/Desventaja; con un objetivo derribado o un efecto que dé ventaja, la ventana debe avisarlo y preguntarte si la usas.'},
 {id:'estados35',titulo:'3.5 · Preguntar antes de un estado',pasos:'Con un PNJ, usa un ataque o técnica que derribe o aturda a un PJ. El DM debe ver «¿Aplicar…?» con lo que provoca y el jugador el aviso en el chat. Responde No: no debe aplicarse. Repite con Sí.'},
 {id:'moneda35',titulo:'3.5 · Pausa para la Moneda Antigua',pasos:'Con un PJ con Monedas Antiguas, falla un ataque y una salvación (sin sacar 1). Debe ofrecerse gastar una para repetir; al aceptar, la tirada nueva cuenta y la tarjeta lo anota.'},
 {id:'sustitucion35',titulo:'3.5 · Sustitución contra un PNJ fuera de combate',pasos:'Sin combate, haz que un PNJ muerda dos veces a un PJ con Sustitución. Las dos veces debe ofrecerse. Deja al PJ sin Verbe y Agotamiento 4: el chat debe explicar por qué no puede y cuánto costaría.'},
 {id:'descanso35',titulo:'3.5 · Descanso Corto solo para gastar',pasos:'Con un PJ herido y Dados de Golpe gastados, haz un Descanso Corto: no debe recuperar dados y debe abrirse la ventana para gastarlos. Prueba «Gastar hasta el tope».'},
 {id:'editor35',titulo:'3.5 · Editar y restaurar una técnica',pasos:'En Dirección → Editar técnicas, cambia los dados de una técnica que sepa un PJ. Su ficha debe mostrar el valor nuevo. Restaura el original y comprueba que vuelve. Borra Getsuga Tenshō del catálogo del mundo.'},
 {id:'devolver35',titulo:'3.5 · Devolver Verbe',pasos:'Usa una técnica y, desde su tarjeta, devuelve 2 de Verbe con un motivo. Debe sumarse sin pasar del máximo y aparecer en la tarjeta y en Dirección → Últimas devoluciones.'},
 {id:'etapas36',titulo:'3.6 · Etapas y naturaleza oculta',pasos:'Despierta una ficha de prueba en etapa Aprendiz con naturaleza secreta. No debe ver técnicas elementales ni poder aprender otra rama. Abre la siguiente etapa desde Herramientas del DM, pide el entrenamiento de naturaleza, da por terminados los días y haz la prueba.'},
 {id:'reserva36',titulo:'3.6 · Reserva por dados',pasos:'Despierta una ficha con «Tirar dados»: el chat debe mostrar una tirada por nivel y el máximo debe ser su suma más la característica. Súbela un nivel: debe tirar ese nivel. Otra ficha en «Promedio» debe quedar como la tabla.'},
 {id:'sangre36',titulo:'3.6 · Una sola sangre',pasos:'En una ficha con linaje, intenta abrirle una Mirada heredada distinta: debe negarse. Como trasplante sí. Con el linaje secreto, el bloque «Sangre de…» del Inicio debe explicarlo y «Activar técnicas familiares» debe abrirlas.'},
 {id:'oponentes36',titulo:'3.6 · Oponentes impredecibles',pasos:'En Diagnóstico, pulsa «Ocultar datos exactos de los enemigos». Con un usuario jugador, comprueba que no ve la barra ni la ficha completa de un PNJ y que el ataque no muestra su CA. Crea dos PNJ con «Verbe variable»: deben salir distintos.'},
 {id:'curacion36',titulo:'3.6 · Curación con reposo',pasos:'Con un PJ con Herida No Tratada, trata con un Maestro de Pulso que tenga Médico del Verbe: la tirada debe llevar ventaja y el bono. Supera la CD por 5: cuenta dos días. Lanza Restauración menor otro día: cuenta dos días y no borra un nivel de golpe.'},
 {id:'cuerpo37',titulo:'3.7 · Técnicas de Cuerpo y de cuerpo a cuerpo',pasos:'Con un PJ que sepa un golpe de Cuerpo de 5 ft, marca a un enemigo al lado y úsalo: debe tirar el ataque y el daño (antes no tiraba nada). Usa un refuerzo de Cuerpo (acción adicional): debe salir la ventana «Qué pasó».'},
 {id:'choque37',titulo:'3.7 · Choque y defensas de cualquier rama',pasos:'Ataca con una técnica de Cuerpo a un PJ despierto que sepa una contratécnica de Velo: debe ofrecerse el choque y, sin ventaja elemental, decidir Control + grado. Con Palma que desvía, la ventana de defensa debe ofrecerla y dar +3 a la CA.'},
 {id:'cargadas37',titulo:'3.7 · Canalizar y liberar',pasos:'En combate, canaliza Lanza de tormenta: el token queda quieto y sin reacción. Pasa un turno y libérala: debe tirar con 1 dado más. Repite y hazle daño mientras canaliza: debe tirar Constitución y, si falla, perder la carga.'},
 {id:'clones37',titulo:'3.7 · Clones con ficha propia',pasos:'Con un PJ que sepa Clon de sombra, úsalo y elige 2 de Verbe: debe aparecer «Clon de…» junto a él con 1 PG y 2 de Verbe. Hazle daño: debe desaparecer y el DM ver la ventana de recuerdos. Crea otro y disípalo desde su panel: debe devolver su Verbe.'},
 {id:'pase327',titulo:'3.27 · El pase del DM con armas y entre PNJ',pasos:'Como DM, marca al Barovian (T) y ataca con Taina con un arma normal: antes de tirar debe salir «¿Le afecta?». Da el pase: sale la tirada sin volver a preguntar. Haz lo mismo marcando después de usar el arma (el botón Ataque de la tarjeta). En Configuración → El pase del DM · cuando el DM mueve a alguien puedes dejarlo en «Solo PNJ contra PNJ» o apagarlo.'},
 {id:'familias327',titulo:'3.27 · Artes de familia por nacimiento',pasos:'Abre el panel de un PNJ despierto sin familia (el Barovian): en Aprender no debe ver Mano gigante ni las de Tinta, ni subiendo Cuerpo o Sello. En la pestaña DM → Naturalezas y linaje, elige una familia (o 🎲) y pulsa Su diario: abre «Mundo 12 · Las familias del Verbe». Guarda: ahora sí ve sus artes.'},
 {id:'azar327',titulo:'3.27 · El 🎲 del DM',pasos:'Al despertar a alguien y en DM → Naturalezas y linaje, pulsa 🎲 junto a Linaje, Familia, Fuerza o Rama: sale una tirada solo para ti y la lista queda elegida (todavía sin guardar). La ventana del linaje se abre para leerlo antes de dárselo. La sangre de la Barrera no sale al azar.'},
 {id:'estudio327',titulo:'3.27 · Aprender por días',pasos:'Con un PJ despierto, en Aprender pulsa «Estudiar» en una técnica de grado 1: paga los Trazos y queda «Estudiando 0/2». «Practicar hoy» tira Control CD 11. Vuelve a intentarlo: dice que hoy ya practicó. Avanza un día (Menú del DM → Día siguiente) y practica otra vez. Como DM, «Aprender ya» la da por aprendida; en DM → Aprender al instante, la ficha aprende al pagar.'},
 {id:'naturaleza327',titulo:'3.27 · Naturaleza por dado',pasos:'Despierta una ficha de prueba con Primera naturaleza «La tira el jugador con un dado». En DM → Naturaleza secreta pulsa «Que tire ya su naturaleza»: en Inicio aparece «Tirar mi naturaleza» con la lista 1 Fuego… 5 Rayo. Tira: sale 1d5 en el chat y la naturaleza queda puesta. Repite para la segunda (1d4).'},
 {id:'reserva327',titulo:'3.27 · Reserva con Constitución',pasos:'Mira la reserva de un PJ: debe sumar su modificador de CON por nivel. Gasta todo y haz un Descanso Largo en Santuario: recupera el 15 % más CON por cada dos niveles (con CON +2 a nivel 5, 12 de 44). Necesita varios días para llenarse.'},
 {id:'economia327',titulo:'3.27 · Acción y reacción Verbe',pasos:'En combate, en el turno de un PJ despierto, usa una técnica de Acción y otra de Acción adicional: el chat dice «Se gastó la acción Verbe» y «Se gastó la acción adicional Verbe», y arriba del panel y en el botón Verbe de la barra quedan «gastada»; en el rastreador, el rayo y la flecha en rojo. Una segunda técnica de Acción (antes del nivel 11) o de Acción adicional ese turno se niega. Su ataque de D&D sigue libre. Al empezar su siguiente turno vuelve a «libre». Ataca con un arma a alguien que sepa Sustitución: le aparece la defensa, gasta su reacción Verbe y el chat dice que no apliques el daño.'},
 {id:'golpe327',titulo:'3.27 · Técnicas de golpe',pasos:'Con un PJ que sepa Golpe hondo, úsalo: pregunta con qué arma atacas (las equipadas primero), tira el ataque de esa arma y el daño suma 1d6 de fuerza (2d6 desde nivel 5). Con Golpe de martillo, el próximo golpe cuerpo a cuerpo suma 2d6 y al tirar su daño el efecto se gasta y el chat recuerda la salvación de FUE.'},
 {id:'pies327',titulo:'3.27 · Todo en pies',pasos:'Abre el panel del Verbe: los alcances dicen «60 ft», no «18 m». El chat del módulo (Eco, clima) también. Las escenas que estaban en metros pasaron a 5 ft por casilla (te llega un susurro la primera vez).'},
 {id:'plantillas327',titulo:'3.27 · Quitar plantillas',pasos:'En Bosque profundo, pulsa la goma de la barra de Tokens (o Menú del DM → Quitar plantillas): lista las plantillas de la escena marcadas y las demás regiones sin marcar. «Quitar todas las plantillas» las borra.'},
 {id:'defensas328',titulo:'3.28 · Defensas de la campaña',pasos:'Al cargar el mundo te llega un susurro con cuántas fichas de VD ½ o más recibieron Coraza, Fortaleza o Cuerpo sordo. Abre el panel del Verbe de un lobo terrible (pestaña DM → Defensa de la campaña): dice cuál tiene y cuál sugiere. Cámbiala a Fortaleza y guarda: su efecto pasa de CA a salvaciones. Un lobo gris (VD ¼) no tiene ninguna.'},
 {id:'ruptura328',titulo:'3.28 · Brecha, Grieta y Quebrado',pasos:'Con un PJ, usa «Romper la guardia» (Acciones de Fuerza) contra el lobo terrible y que falle: queda con Brecha y su CA baja 2. Repite hasta 4 veces: nunca pasa de 3 Brechas. Usa «Buscar la grieta»: Grieta, −2 a sus salvaciones. Ponle Quebrado desde los estados del token: su Coraza se apaga ese turno y el daño ignora sus resistencias.'},
 {id:'pesada328',titulo:'3.28 · Técnica pesada',pasos:'Con un PJ que sepa «Mil aves en la palma» o una esfera, ataca al lobo terrible con Coraza: el ataque suma lo que la Coraza le daba (la atraviesa) y sale la tarjeta «Técnica pesada» avisando el ataque de oportunidad. Con un ojo abierto, la tarjeta dice que no abre su guardia.'},
 {id:'defensaPedida328',titulo:'3.28 · Defensa a pedido',pasos:'Con un jugador conectado, que use Presa contra un PNJ marcado: a ti te sale «Te defiendes» con Fuerza y Destreza; tira y, si falla, el PNJ queda Agarrado solo. Al revés, usa el Empujón de un PNJ contra el PJ marcado: al jugador le sale la ventana, sin ver la CD.'},
 {id:'choque329',titulo:'3.29 · Lo que deja un choque',pasos:'Haz chocar dos técnicas cuyos grados sumen 3 o más (Choque de técnicas en la pestaña DM, o una técnica contra un token con Verbe): sale la tarjeta «Lo que deja el choque» con la explosión (tira salvaciones de DES a los tokens cerca), aparece una región «Terreno vivo: …» y, si uno perdió por 3 o más, recibe el contragolpe y queda Desequilibrado (por 5 o más, Mano rota).'},
 {id:'propio332',titulo:'3.32 · Lo propio es tuyo y el control vuelve',pasos:'Marca a un enemigo (T) y usa Guardia de hierro (o cualquier técnica de alcance «Yo») con un PJ: no debe salir «¿Le afecta?» y el efecto (+1 CA, velocidad 0) se pone en quien la usó. Si alguna vez no puedes mover fichas, Menú del DM → Mesa → «Recuperar el control»: no sale el pase por el marcado, el efecto queda en el usuario y el control vuelve sin F5.'},
 {id:'estados332',titulo:'3.32 · Estados explicados y descansos',pasos:'Pon Derribado y Agotamiento 2 a un token y pasa el ratón por sus iconos en el panel de estados y en el HUD (clic derecho). Luego tira un Descanso Largo con un PJ: cada estado dice qué significa y qué hacer (el Agotamiento, −2 a d20 y −10 ft) y el Descanso Largo no devuelve PG, ofrece gastar Dados de Golpe.'},
 {id:'turno333',titulo:'3.33 · El turno a la vista',pasos:'Empieza un combate con un PJ y un enemigo. Bajo el carrusel sale la barra del turno: mueve el token 10 ft y mira que el movimiento baje; usa un ataque y mira que la Acción quede gastada; como DM prueba «Devolver movimiento». Pon al PJ adyacente al enemigo y aléjalo: sale el aviso de ataque de oportunidad con Desengancharme, Moverme igual y No me muevo. Empieza un turno Derribado: pregunta si te levantas. Al entrar al combate, el jugador elige ventaja, normal o desventaja para su iniciativa.'},
 {id:'verbe334',titulo:'3.34 · Forzarse, manos ocupadas, Sustitución, escapes y Moneda',pasos:'Deja a un PJ con 0 de Verbe y usa una técnica: pregunta si te fuerzas y te llega un susurro con el riesgo y cómo recuperarte. Empieza a canalizar una técnica cargada e intenta atacar con un arma o mover el token: sale «¿Cancelas y recuperas tu Verbe?». Defiéndete con Sustitución: eliges la casilla adyacente. Usa Sombra bajo el salto: eliges a dónde caer y ofrece Golpe hondo. Usa un escape de su rama: los enemigos cercanos tiran Percepción o Arcanos. Junto a la barra del Verbe de la hoja está el botón de la Moneda; en combate gasta la acción Verbe. Gana un choque: el ganador queda con Ímpetu y el perdedor con Brecha.'},
 {id:'muerte335',titulo:'3.35 · A 0 PG, el precio de volver y descansar fuera del Santuario',pasos:'Baja a un PJ a 0 PG en combate: queda Acechado sin reacción (la barra del turno lo dice) y si intenta atacar o lanzar algo sale el aviso; tomar una poción sí deja. Tras su salvación de muerte automática le ofrece otra con ventaja gastando su acción (si falla, +1 Agotamiento). Cuando vuelva, tira CON CD 8 + 2 × su Agotamiento; con un 20 natural se quita 1 de Agotamiento y te sale el botón «Darle su turno ahora». Apaga el Santuario y tira un Descanso Largo: la ventana deja gastar la mitad de Dados de Golpe.'},
 {id:'accion336',titulo:'3.36 · Acción estándar, daño indirecto y volumen para todos',pasos:'Abre una hoja (PJ o PNJ) y pulsa «Acción estándar» en su cabecera: salen las acciones de cualquiera explicadas y lo de su hoja separado en Acción, Adicional y Reacción; usa una. Como DM, selecciona tokens y abre Menú del DM → Mesa → «Daño de caída e indirecto» con 30 ft: 3d6 y Derribado. Pon música: la barra del reproductor tiene un control de volumen que no desaparece; el del DM baja la música de todos. A una hoja con Maestro del escudo, su «Empujón: derribar» dice +2 a la CD.'},
 {id:'reliquias337',titulo:'3.37 · Almacén de reliquias, conjuros y subir de nivel',pasos:'Menú del DM → Mesa → «Almacén de reliquias»: en la pestaña Objetos aparece «Reliquias del Abismo (solo DM)» con el manual, las copias por etapa y las de entregar; arrastra una de entregar a una hoja y súbela de etapa con el botón de su cabecera. En el libro de conjuros: «Aprender conjuros» (con Mayús salen todos, sin filtro de lista) y «Quitar conjuros»; en un PNJ mago también sale y pregunta su lista. Abre un conjuro de PF2e: dice «Nivelado a D&D» y ya no habla de Alzar un escudo. En una hoja de PJ, «Subir de nivel» muestra qué gana y abre el asistente.'},
 {id:'tutorial338',titulo:'3.38 · Tutorial, dotes de elemento, auditoría y fama',pasos:'En el panel del Verbe → Ayuda rápida, abre «Tutorial»: explica el Control, los choques, la acción Verbe, forzarse, Brecha y Grieta y cómo escapar. En Aprender técnicas cada una dice «⚔ Choca» o «No choca». Con un PJ sin naturaleza descubierta, las dotes de elemento no aparecen (sale el aviso). Práctica de Control explica qué es el Control. Reserva profunda dice «Automática». Menú del DM → Mesa → «Proeza (fama)»: suma fama a un PJ y, al cruzar un umbral, te llega un susurro con las facciones.'},
 {id:'estilos368',titulo:'3.68 · Estilos de rama',pasos:'(1) Con un PJ en rango Entrenado de Quietud: Panel → Mejorar → Dotes → categoría «Estilos de rama»: aparecen «Centinela del mundo» (estilo) y «Lengua de lo salvaje» (oficio); el segundo paso «Contragolpe» sale bloqueado (pide el estilo, nivel 5 y Experto). (2) Compra «Lengua de lo salvaje»: queda en «Entrenando» (4 h, CD 12); al terminar, la hoja tiene competencia en Naturaleza (efecto «Beneficios del Verbe»). Quitar la dote (DM) la retira. (3) Reglas de la casa → «19 · Plan de estudios del sensei» incluye los pasos 2.6 y 3.6 de estilos. Esperado: 36 dotes, 3 por rama salvo Sangre; cada una dice a qué dote o rasgo de D&D equivale.'},
 {id:'tecnicas367',titulo:'3.67 · Auditoría de técnicas: fichas, Sello, Velo, Quietud e Hilo',pasos:'(1) Abre cualquier técnica aprendida: la ficha dice, en orden, «Qué es», «Aspecto», «Qué hace» y «Cómo se usa» (con Tirada, Área y Daño o Curación al final). Ya no aparecen frases como «Afecta solo al objetivo o área indicados» ni «Lo de D&D es el golpe». (2) Con dos PJ despiertos, ataca con Lanza de sello: no se abre la ventana de choque, y una técnica de Sello no aparece como contratécnica. Ajustes → «Verbe: los sellos no chocan» apagado: vuelven a chocar. (3) Usa Sello de silencio o Barrera menor: no piden Concentración. Sello de cierre y Círculo de guarda duran 7 días. (4) Cualquier técnica de Velo tiene un párrafo «En combate» o «Fuera de combate». (5) Quietud: El mundo cura se usa con una acción; Raíz en el suelo dura 1 minuto sin Concentración y da ventaja en ataques de oportunidad. (6) Hilo: Lluvia de agujas con 20 Agujas en la hoja: el chat dice «gasta 10 Agujas (quedan 10)» con «Deshacer» (DM); sin agujas, avisa que no las lleva. Ajustes → «Hilo: herramientas del Verbe» lo apaga. Esperado: fichas en el orden nuevo; Sello sin choques ni Concentración salvo las de daño; Velo con doble uso; las agujas se descuentan y «Deshacer» las devuelve.'},
 {id:'verbe366',titulo:'3.66 · Todo con Trazos se entrena, técnicas místicas y reacciones',pasos:'(1) Mejorar → Especialidades → «Subir a Entrenado»: cobra los Trazos y queda «Entrenando …» (días buenos según el rango, CD 11 + rango); en «Entrenando» se tira. Lo mismo con «Volverte competente» en Control (2 días, CD 13; pericia 3 días, CD 15). El DM tiene «Dar por aprendida»; ajuste «Verbe: rangos y Control se entrenan». (2) Aprender técnicas: ya no aparecen las utilidades mundanas (Higiene de las manos, Memoria de la receta, Nudo del porteador…: 32); quien las sabía las conserva. (3) Papel que estalla: es acción adicional (detonar, a 120 ft); pegarlo es tu interacción con un objeto. (4) «Romper el Velo» ahora es «Liberar el Velo», una reacción Verbe. (5) Una técnica de 0 Verbe con mejoras cultivadas cuesta 1 Verbe por mejora. (6) La guía y los tiempos explican la Reacción Verbe: convierte en reacción una técnica de acción o adicional para chocar.'},
 {id:'verbe365',titulo:'3.65 · Familia = linaje, Control con INT y ramas que se abren entrenando',pasos:'(1) Despertar a alguien: ya no hay «Familia de nacimiento» ni «Naturaleza oculta» ni segunda fija; la naturaleza sale con su dado. En DM → Naturalezas y linaje, la familia se muestra según el linaje. (2) La habilidad Control del Verbe de una hoja nueva usa Inteligencia; DM → «Control del Verbe» INT/SAB/CAR la cambia a mano; las dotes Control por instinto (don, SAB) y Control por presencia (entrenada, CAR) la cambian solas. Un susurro al DM lista las fichas que seguían con Sabiduría. (3) Mejorar → Especialidades: una rama que no es la principal ni empezaste sale «Cerrada» con «Abrir · 2 Trazos»: queda en «Entrenando» (2 días buenos, CD 13); al terminar se abre. El DM puede abrirla en su pestaña. (4) Practicar una técnica pregunta con qué tiras (Control, Sabiduría por instinto o, con guía, otra característica). (5) Árbol de Control: Control fino pide Práctica de Control y nivel 3; Choque perfecto pide Leer el flujo. Ajuste «Verbe: las ramas no se abren solas».'},
 {id:'entreno364',titulo:'3.64 · Dado de control, dotes entrenadas y crecer entrenando',pasos:'(1) Con un PJ Aprendiz usa una técnica: el recibo de la tarjeta dice «incluye el dado de control 1d4: N» y la reserva baja el coste más el dado; con Verbe justo, el dado se lleva hasta el límite pero la técnica sale. La ficha de la técnica dice «cuesta 2 + 1d4». (2) Panel → Mejorar → Dotes: dos bloques, «Dones» y «Dotes entrenadas», y un filtro Tipo. Compra Práctica de Control: cobra 2 Trazos y queda «Entrenando 0/1»; en la pestaña nueva «Entrenando» tira (eliges Control, Sabiduría o, con guía, otra característica); un 20 la da al instante. «Dejar» devuelve los Trazos; el DM tiene «Dar por aprendida» y el ↔ para pasar una dote de don a entrenada. (3) «Entrenando» → Entrenar o meditar: CD 15, 5 días buenos = 1 Trazo (4 con compañero, 3 con sensei), hasta 2 por nivel. (4) Mis técnicas: chips por activación (Acción Verbe, Adicional, Reacción, Fuera de combate); Aprender: «Solo las que estoy entrenando». (5) Guardia de Verbe: +1 CA y +1 a todas las salvaciones. Ajustes: «Verbe: dado de control» y «Verbe: dotes entrenadas».'},
 {id:'sensei364',titulo:'3.64 · Plan de estudios del sensei',pasos:'Reglas de la casa → «19 · Plan de estudios del sensei»: fases 0 a 4 con qué enseña el sensei, qué se hace en la hoja, Trazos, días y CD de cada paso, y la prueba para subir de etapa (Practicante CD 13, Iniciado CD 15, Pleno CD 18). En el panel, «Entrenando» muestra tu etapa y qué te falta para la siguiente.'},
 {id:'legendarias363',titulo:'3.63 · Armas legendarias con etapas',pasos:'Menú del DM → «Almacén de reliquias»: en Objetos → Reliquias del Abismo aparece «3 · Armas legendarias» con las 17 (Fauces de la Marea, Trueno en Láminas…) y su manual en «1 · Manual del DM». Arrastra una a un PJ: llega sin identificar (por ejemplo «Espada larga · sin identificar») y ataca como un arma común. «Estudiar» o el DM la suben: Dormida +1 (sintonía), Despierta +2 y su poder como actividad con sus usos (Lámina que estalla: salvación de DES y 3d6 de fuego en 5 ft, 1 por descanso corto), Resonante +3 y el poder completo. «Bajar» la devuelve. Equipada cuenta como artefacto para las técnicas del Verbe que lo piden. «Historia secreta» abre su página.'},
 {id:'menores363',titulo:'3.63 · Reliquias menores y objetos del Verbe',pasos:'Menú del DM → «Reliquias menores y objetos del Verbe»: en Objetos aparece «Reliquias menores (solo DM)» con subcarpetas Nivel 1 · comunes, Nivel 3 · poco comunes, Nivel 5 · raras y Nivel 11 · muy raras (los objetos mágicos de D&D, traducidos, sin legendarios), cada uno con la nota «Reliquia menor · desde nivel X · sin etapas», y «Objetos del Verbe» (tinta, sellos, agujas, estrellas arrojadizas 1d4 20/60 ft, hilo, marionetas, maletín). Repetirlo no duplica. «Quitar reliquias menores» lo revierte.'},
 {id:'reliquias362',titulo:'3.62 · Reliquias sin identificar e historias secretas',pasos:'Menú del DM → «Almacén de reliquias». En Objetos → Reliquias del Abismo → 2 · Para entregar, las copias salen «(Sin identificar)». Arrastra una (por ejemplo Acero del Velo Herido) a la hoja de un PJ: el jugador la ve como «Barra de acero negro mate · sin identificar» con su aspecto y cómo identificarla (las secciones de abajo «sin identificar» y «para el chat» ya tienen texto). El clic de «Identificar» de D&D no le sirve; su botón «Estudiar» tira Arcanos/Historia/Investigación contra la CD (ventaja con Detectar magia o Tacto del archivero); si falla, espera a un Descanso Largo; si acierta pasa a Dormida y el chat trae «Deshacer» (DM). Como DM: «Subir etapa» / «Bajar» (0 a 3) y «Historia secreta» en la cabecera (abre su página en los diarios «Reliquias · Historias secretas…», solo DM, o la empieza en blanco). El manual del DM muestra la CD, cómo la ve el jugador y el enlace a su historia.'},
 {id:'nivelpnj362',titulo:'3.62 · Nivel PNJ',pasos:'Abre la hoja de un PNJ (DM): en la cabecera, «Nivel PNJ». Muestra qué gana al subir (VD, PG por sus dados, +2 a su mejor característica en VD 4/8/12/16/19, +1 CA en VD 4/5/8/10/13/17, nivel de lanzador y del Verbe) y qué pierde al bajar. «Subir 1», «Bajar 1» (deshace exacto la última subida) o «Ir a ese VD». El chat del DM trae el resumen y «Deshacer».'},
 {id:'oculta361',titulo:'3.61 · Información oculta y estados enlazados',pasos:'Como jugador, pasa el ratón por un enemigo: ya no dice cómo está (Health Estimate solo lo ve el DM). Con «Escuchar el cuerpo» (Pulso; ahora dura 1 minuto con concentración) o el estado «Escuchando los cuerpos» puesto por el DM, al pasar el ratón por una criatura a 30 ft sale «PG x/y · estados». Diarios: aparece «Ecos · Estados alterados» con una página por estado. En una descripción, el chat o el panel del Verbe, palabras como Derribado, Grieta, Empapado o Coraza están subrayadas: un clic abre su página. Ajustes: «Ocultar cómo están los demás» y «Estados enlazados».'},
 {id:'estilos360',titulo:'3.60 · Estilos de hoja oscuros y con textura',pasos:'Abre la hoja de un PJ con un estilo (paleta de la cabecera): fondo oscuro con grano suave y nubes de textura, tonos apagados (brasa, profundidad, musgo, ciruela, pizarra), marco fino doble y filigrana en las cuatro esquinas; los textos se leen bien (tema oscuro de dnd5e). «Original» devuelve la hoja y su tema de siempre. Una hoja de PNJ sale en «Tinta» (cuero oscuro y rojo). En tus ajustes, «Ver los estilos de hoja» los apaga para ti.'},
 {id:'asistente359',titulo:'3.59 · Asistente de combate y escenario cambiante',pasos:'Crea una escena: pregunta qué escenario es (también en su configuración: «Escenario (Ecos)»). Pon PJ, un PNJ amistoso y hostiles; empieza un combate: el Asistente pregunta el escenario, el bando de cada ficha del tablero (aliado, neutral, hostil) y si está en el combate; el balance cuenta a los aliados y da consejos del lugar. «Empezar con esto». En cada turno se tira 1d20: con el umbral sale «¡Pasa algo!» (al DM, o a todos si lo marcaste) con su CD y dados nivelados; «Resolver» tira las salvaciones, aplica daño y estado, y «Deshacer» lo devuelve; «Otro suceso» saca otro. Menú del DM: «Asistente de combate», «Suceso del escenario ahora», «Etiqueta de la escena». Al arrastrar una criatura, el balance también suma a los aliados PNJ.'},
 {id:'festejo358',titulo:'3.58 · Festejo del enemigo (terror y burla)',pasos:'Con «Festejo: de quién» en «Solo los personajes de los jugadores» y «Festejo del enemigo» encendido: un PNJ que saca 20 natural en una tirada pública muestra a los jugadores la pantalla de terror (oscuridad roja, latido, grietas, gotas, retrato en negativo, «¡GOLPE MORTAL!» y «Prepárense…») con un retumbe y un latido sintetizados. Con un 1 natural: «¡FALLÓ!» con un duendecillo que se ríe y un trombón triste. Menú del DM → Festejo del 20: «20 de enemigo (terror)» y «1 de enemigo (burla)» lo lanzan a mano. Un clic lo salta.'},
 {id:'acciones357',titulo:'3.57 · Menú de acciones, barra del turno y Sorpresa',pasos:'(1) Barra izquierda → «Acciones disponibles»: arriba, las pestañas Acción / Adicional / Reacción / Fuera de combate con cuántas hay; tachadas si ya las gastaste. En Acción: Atacar (armas), Magia (conjuros preparados; los que no tienen espacio salen apagados), De tu hoja y De cualquiera; en Adicional aparecen Apuntar, Fintar, Aguantar… y lo de la hoja. Clic usa la actividad. Lo mismo en la ventana del botón «Acción estándar» de la hoja. (2) La barra del turno bajo el carrusel se arrastra por el título, A−/A+ la achica o agranda, – la minimiza, ⌂ la vuelve a su sitio. (3) Arrastra el token de quien actúa sin soltar: la barra baja y sube con lo que costaría; en rojo si no alcanza. Un jugador sin pies no puede mover (Correr o «Devolver movimiento» del DM). (4) Botón «Sorpresa» (DM): Sorprendido no reacciona (ni D&D, ni Verbe, ni choques, ni oportunidad), lo atacan con ventaja y se va al terminar su primer turno.'},
 {id:'arreglos356',titulo:'3.56 · Arreglos de la prueba del 12-nov',pasos:'(1) En combate, lanza un conjuro con un PNJ (Miria) desde su hoja: la barra del turno marca su Acción (o Adicional/Reacción según el conjuro). (2) Selecciona un PNJ y ponle actitud Hostil en el panel de acciones; selecciona otro token del mismo actor: muestra la suya (Indiferente). (3) Menú del DM → Relojes de facción: la lista se desplaza con la rueda y los botones quedan abajo a la vista. (4) En el rastreador, «Tirar todas» o «Tirar PNJ» abre la ventana para elegir Ventaja/Normal/Desventaja de cada uno (los jugadores ya vienen marcados).'},
 {id:'venenos355',titulo:'3.55 · Venenos por etapas y taller',pasos:'Dale a un PJ un veneno del compendio «Objetos de PF2e (Ecos)» → Venenos (por ejemplo Dram nocaut). En su hoja, botón «Usar veneno»: untar un arma o exponer a un objetivo marcado. El PNJ tira solo (CD de CON); el PJ tiene «Tirar». Con fallo aparece el efecto «Veneno: … · etapa 1» con sus estados; avanza el tiempo del mundo (o pasa asaltos): en cada intervalo pide otra salvación, sube o baja de etapa, aplica el daño con «Deshacer daño», y se cura en 0 o al pasar su duración. Menú del DM → «Venenos activos»: bajar, subir, curar. Inventario → «Taller» → «Nuevo proyecto»: herramienta, CD, días y materiales; tira, paga y queda el proyecto; «+1 día» hasta terminar (el objeto aparece) y «Deshacer» en el chat; «Cancelar» devuelve el dinero. Reglas de la casa: página 18.'},
 {id:'conjuros354',titulo:'3.54 · Conjuros por huecos',pasos:'En la hoja de un PJ lanzador (por ejemplo Miria), pestaña Conjuros: arriba aparece «Conjuros por nivel» con los huecos de su clase (Trucos y Preparados, o Libro gratis si es maga) y cuántos faltan. Toca un + vacío de trucos: el buscador abre solo trucos de su lista (D&D y PF2e) y deja elegir como mucho los que faltan. Un + de preparados: si hay conjuros sin preparar en la hoja ofrece prepararlos; «Buscar uno nuevo» los suma ya preparados. «Quitar conjuros» o despreparar los devuelve. Sube de nivel: llega el aviso con el botón al libro.'},
 {id:'dotes353',titulo:'3.52/3.53 · Dotes menores por nivel y especies de PF2e',pasos:'Menú del DM → «PF2e: dotes, especies y objetos» deja tres compendios (Dotes, Especies y herencias, Objetos de PF2e). En la hoja de un PJ de nivel 6 aparece la pestaña «Dotes» con el número rojo de huecos por llenar (niveles 2, 3, 5 y 6). Toca un hueco: la lista muestra solo las de su clase/especie y nivel; «Ver también las que todavía no puedes tomar» dice qué falta. «Tomar» la suma (Rasgos y chat con Deshacer); la × la quita. Como DM: «Sin filtros», «Asignar una dote a mano» y clase/ascendencia/herencia para las dotes. Sube el PJ a nivel 7: llega el aviso con el botón a la pestaña. En un PNJ, Rasgos → «Sumar dotes de PF2e».'},
 {id:'estilos351',titulo:'3.51 · Estilos de hoja y traducción con respaldo',pasos:'Abre la hoja de un PJ: en la cabecera, la paleta abre los cinco estilos (Llama, Marea, Hoja, Sombra, Tormenta) y «Original»; cambia el color, los adornos de las esquinas y las letras del nombre. Una hoja de PNJ sale en «Tinta» (ajuste del mundo para cambiarlo). En tus ajustes, «Ver los estilos de hoja» los apaga solo para ti. Menú del DM → «Traducir fichas»: solo traduce lo que sigue en inglés, y «Deshacer la última traducción» lo devuelve.'},
 {id:'reglas350',titulo:'3.50 · Lo que D&D base no hace',pasos:'En combate: (1) ataca a un enemigo detrás de una pared o de otra criatura: la tirada trae −2 o −5 y el chat dice por qué. (2–3) Pasa por una región de terreno difícil o pon «Terreno difícil» en la barra del turno: el movimiento cuenta el doble; trepar o nadar sin esa velocidad también. (4) Panel → Saltar: tabla de salto y modo salto. (5) Marca «Objeto» en la barra. (6) Lanza dos conjuros con espacio en el mismo turno: avisa con «Lanzar igual». (7) Preparar: anota la acción; «¡Ahora!» gasta la Reacción; se borra en su turno. (8) Marca a un PNJ y usa Influir: te llega la CD de su actitud y botones para cambiarla; pon su actitud en el panel. (9) Dale Inspiración a un PJ desde el panel: en su tirada sale «Repetir con Inspiración» (con Deshacer). (10) Agarra a alguien con Presa y muévete: viene contigo y cuesta el doble (con Deshacer).'},
 {id:'festejo347',titulo:'3.47/3.49 · Festejo del 20 natural (estilo anime de acción)',pasos:'Se ve con líneas de foco, trazo de tinta, panel de manga con aura y letras de impacto, naranja y negro (o el color de la naturaleza del Verbe). Menú del DM → Mesa → «Festejo del 20» → «Probar (solo yo)» con un token seleccionado: sale el corte a pantalla completa con su retrato y «¡CRÍTICO!»; un clic lo salta. «Lanzar un 20 a todos»: lo ven los jugadores conectados. Un jugador saca un 20 natural en un ataque: lo ven todos; en la salvación de muerte dice «¡SE LEVANTA!»; un 1 es «¡PIFIA!» en rojo. En el panel de acciones, la estrella pone la frase propia del personaje. Apaga el temblor en tus ajustes y el festejo entero en los del mundo.'},
 {id:'ventaja346',titulo:'3.46 · Ventaja y desventaja por estados',pasos:'Pon a un enemigo Derribado y atácalo desde una casilla pegada: la ventana de la tirada ya viene en Ventaja y el chat dice por qué; desde lejos, Desventaja. Usa Esquivar con un PJ y atácalo: Desventaja. Marca a un aliado (T) y usa Ayudar en el panel: queda «Ayudado» y su próxima tirada sale con Ventaja (y se gasta). Esconderse tira Sigilo y deja Escondido con 15 o más; al atacar se pierde. Cambia el modo a mano en la ventana: respeta lo que elijas.'},
 {id:'reaccion346',titulo:'3.46 · Reacciones del Verbe a la vista',pasos:'En combate, con un PJ despierto que conozca una reacción de alcance (Coser la herida, 18 m) a menos de 60 ft de un aliado: que un enemigo ataque al aliado. A su jugador (o a ti si es PNJ) le llega «Reacción Verbe» con la distancia, el costo y el botón Usar, y su retrato brilla en el carrusel 30 s. Aléjalo a más de 60 ft y repite: no avisa.'},
 {id:'boton346',titulo:'3.46 · Botón «Acciones disponibles» en la barra izquierda',pasos:'Bajo el botón del Verbe (gota) está el de Acciones (puño): un clic muestra u oculta el panel de acciones; Mayús+clic abre la ventana completa de Acción estándar de la ficha seleccionada.'},
 {id:'reliquia346',titulo:'3.46 · Reliquias con aspecto, qué es y su hito',pasos:'Corre «Almacén de reliquias» en el Menú del DM. Abre una copia de «2 · Para entregar»: muestra Aspecto y Qué es, y no dice cómo se despierta. Su manual (carpeta 1) trae el hito propio para llegar a Resonante.'},
 {id:'panel345',titulo:'3.45 · Panel de acciones, ventanas y reliquias',pasos:'A la izquierda está el panel «Acciones»: selecciona un token y cambia; en combate marca Acción, Adicional y Reacción (clic otra vez para devolverla) y descuenta el movimiento; prueba Esquivar, Correr y Desengancharse (con Mayús gasta la Adicional). Arrástralo desde su cabecera y plégalo. Abre cualquier ventana del módulo: se agranda desde la esquina y se desplaza con la rueda. Menú del DM: las descripciones ya no se descuadran (entera al pasar el ratón). Corre «Almacén de reliquias»: quedan dos carpetas (Manual del DM y Para entregar) y en una copia para entregar el botón «Subir etapa (DM)» funciona. El icono de Fortaleza se ve bien. Abre un PNJ cualquiera: tiene las Acciones de Fuerza, Destreza, etc.'},
 {id:'balance344',titulo:'3.44 · Balance del encuentro al arrastrar',pasos:'Arrastra a la escena una criatura hostil de VD alto (por ejemplo VD 5 con el grupo en nivel 2): sale «Balance del encuentro» con el grupo marcado, la etiqueta LETAL y el aviso de criatura letal por sí sola. Desmarca un PJ y mira cómo cambia. Pulsa «Colocar» en «Interesante» (aparecen junto al token) y luego «Deshacer lo colocado»; «Quitar el token que puse» lo borra. Marca «No preguntar más en esta escena» y arrastra otra: ya no sale. Menú del DM → Mesa → «Balance del encuentro» lo abre a mano.'},
 {id:'mesa343',titulo:'3.43 · Relojes, defensa a la vista, siluetas y viajes',pasos:'Menú del DM → Mesa: «Relojes de facción» (mueve uno con + y −, escribe un número; cada cambio te llega con Deshacer), «Viaje por zonas» (3 días en el bosque, ritmo rápido: mira el resumen, arma un encuentro y pulsa Deshacer: el reloj vuelve), «Tokens a silueta» (pasa dos y luego «Deshacer todas»). En la escena, una criatura con Coraza tiene anillo azul y «C+n»; en Configuración del módulo, «Defensa a la vista» cambia quién la ve.'},
 {id:'suceso342',titulo:'3.42 · Suceso del día y Deshacer',pasos:'Avanza el reloj al día siguiente: te llega un susurro «Suceso del día» con la tabla de la estación y los botones Otro, Elegir a mano, Deshacer, Volver al anterior y Contar a la mesa; pruébalos todos. Menú del DM → Mesa → «Suceso del día» apaga el automático. Después, cruza una capa del Abismo y pulsa «Deshacer» en el resumen: el Agotamiento, los PG y el Envenenado vuelven a como estaban. Lo mismo con un mensaje de fama.'},
 {id:'capas341',titulo:'3.41 · Capas del Abismo',pasos:'Menú del DM → Mesa → «Capas del Abismo»: pon la escena en la capa 3 y guarda. «Cruzar hacia afuera» de la 3 a la 0 con un PJ: tira tres salvaciones de CON (capas 3, 2 y 1; la 1 solo si marcas «más de un día» o «durmió») y aplica Agotamiento, daño y Envenenado; lo que no es número te llega en un susurro. Marca «durmió» y mira que cobre como una capa más honda. «Amanecer: la llamada» en la capa 3 tira Sabiduría CD 13.'},
 {id:'jugador339',titulo:'3.39 · La barra del turno desde el jugador',pasos:'Con un jugador conectado y su PJ en su turno: que marque y desmarque «Acción» en la barra, que use Correr (el movimiento sube) y Desengancharse. Antes no le hacía nada; ahora cambia para todos. Si está Derribado al empezar, «Me levanto» descuenta la mitad del movimiento.'},
 {id:'muerte339',titulo:'3.39 · La salvación extra a 0 PG',pasos:'Deja a un PJ a 0 PG en combate y pasa a su turno: tras la salvación de muerte del turno, a su jugador le sale «¿gastas tu acción para otra con ventaja?». Antes no salía nunca. Si falla, +1 Agotamiento.'},
 {id:'clones339',titulo:'3.39 · Lo que entrena un clon',pasos:'Con un PJ que tenga una técnica de clones: crea un clon, avanza el reloj del mundo 8 horas y disípalo. La ventana de recuerdos sugiere las horas: al enviar, el chat dice +1 día de entrenamiento guardado (o el entrenamiento de su naturaleza se acorta). El panel muestra los días guardados; al aprender o cultivar una técnica se gastan solos. Dos clones con 40 h el mismo día: solo cuenta hasta su competencia.'},
 {id:'sangres326',titulo:'3.26 · El diario de cada sangre',pasos:'Abre el panel del Verbe de un PJ, pestaña DM, «Naturalezas y linaje»: cambia el linaje en la lista. Debe abrirse la ventana «Sangre · …» con el resumen y el botón «Abrir su diario», que lleva a su página de «Mundo 11 · Las sangres de los dioses». Lo mismo al elegir un ojo en «Despertar un ojo» y al despertar a alguien. El botón «Su diario» la vuelve a abrir.'},
 {id:'pase326',titulo:'3.26 · El pase del DM',pasos:'Con un jugador conectado, que marque a un PNJ (T) y use una «Acción de Carisma» (Fintar) o una técnica. Al DM le llega «¿Le afecta?»: desmarca o da el pase. Con pase, la acción sigue normal; sin pase, no se gasta nada y el jugador recibe en privado «no le afecta». Con el DM usando la acción, o sin objetivo, no pregunta.'},
 {id:'conjuros326',titulo:'3.26 · Aprender conjuros',pasos:'En la hoja de un PJ con clase que lanza conjuros, pestaña Conjuros: arriba aparece «Aprender conjuros». Abre el buscador con su lista (D&D y PF2e mezclados) y suma lo elegido. En «Reglas de la casa» aparece «15 · Conjuros: cómo sumarlos a tu hoja».'},
 {id:'musica39',titulo:'3.9 · Música de YouTube',pasos:'En Mesa Ecos → Control, pega un enlace de YouTube y pulsa Reproducir: un jugador debe oírlo y ver el recuadro abajo a la izquierda. Pausa y Seguir: los dos en el mismo punto. El jugador recarga: retoma donde iba. Añade dos a la cola: al terminar uno suena el siguiente. El volumen y «Silenciar» del jugador solo cambian lo suyo. El recuadro se mueve desde su barra y cambia de tamaño desde la esquina o con − y +; al recargar vuelve donde lo dejaste.'},
 {id:'compat310',titulo:'3.10 · Foundry 14 y dnd5e 6 sin midi-qol',pasos:'Con un PJ despierto, usa una técnica de ataque marcando un enemigo: debe salir la ventana Normal / Ventaja / Desventaja y tirar el ataque; luego el daño desde la tarjeta. Usa una de salvación con área: debe pedirte colocar la región. Saca un 1 natural con un PJ: debe ofrecer la Moneda Antigua. En combate, una tirada de d20 debe proponer la tabla del d20.'},
 {id:'panel310',titulo:'3.10 · Mis técnicas: filtros, favoritas y paso a paso',pasos:'Abre el panel del Verbe → Mis técnicas. Pulsa los filtros por tipo (Ataque, Salvación…): la lista cambia y el número coincide. Marca una estrella: esa técnica sube arriba y sigue marcada al reabrir. Despliega «Así se resuelve, paso a paso»: debe mostrar el bono de ataque o la CD y el daño de la ficha.'},
 {id:'repetir310',titulo:'3.10 · Repetir canción',pasos:'En Mesa Ecos → Control, pon un video corto y pulsa «Repetir: no» para que diga «sí». Al terminar, debe volver a empezar para todos a la vez. Desactívalo: al terminar debe pasar al siguiente de la cola.'},
 {id:'compendio311',titulo:'3.11 · Compendios del Verbe',pasos:'Recarga el mundo como DM. En «Reglas de la casa» debe aparecer «11 · Compendio del Verbe» con ramas, naturalezas y dotes, y un diario «Ecos · Compendio del Verbe (solo DM)». Un jugador sin personaje despertado no ve ninguno de los dos; uno con personaje despertado ve solo el primero. Haz una prueba de habilidad: la consola no debe mostrar errores de adv-reminder.'},
 {id:'acciones312',titulo:'3.12 · Acciones de cualquiera, el 20 y el 1, armas y mercader',pasos:'Abre la hoja de un PJ: debe tener Golpe sin armas y «Acciones de Fuerza… de Carisma». Usa Presa con un enemigo marcado: salva FUE o DES y, si falla, queda Agarrado. Saca un 20 en un ataque: el daño se duplica (crítico del Manual, desde 3.14) y además sale la tabla del 20. Usa una técnica de Cuerpo: pregunta «¿Con qué atacas?». Con espada y escudo, una técnica con Gestos avisa de las manos. En Mesa Ecos → Control, sortea el mercader extraño y compra algo con Monedas Antiguas. En el panel del Verbe, «Cambiar Monedas» da 1 Trazo por Moneda, como mucho 2 en cada nivel.'},
 {id:'tactico313',titulo:'3.13 · Combate táctico y diarios ordenados',pasos:'Recarga el mundo como DM. En «Reglas de la casa» debe aparecer «14 · Combate táctico», y los diarios «Ecos · …» del DM que estaban sueltos deben estar en «Mesa, tramas y personajes [DM]», numerados. En Mesa Ecos → Control, «Combate táctico» debe estar encendido. Pon a un PJ y un aliado en lados opuestos de un enemigo: el ataque cuerpo a cuerpo del PJ suma +2 «Desprevenido». Usa Fintar: si el enemigo falla, queda Desprevenido. Marca a un PNJ como secuaz y hazle 1 de daño: cae a 0 PG. Marca a un líder enemigo y déjalo a 0 PG: el DM recibe en privado las salvaciones de moral. Usa Evaluar al enemigo con un blanco marcado: llega un susurro con lo que ganaste.'},
 {id:'base314',titulo:'3.14 · D&D primero',pasos:'Saca un 20 natural en un ataque: los dados de daño se tiran dos veces (crítico del Manual) y además sale la tabla del 20. En la hoja de un pícaro o bardo con Pericia en Engaño, usa Fintar: la CD de la tarjeta es 8 + su Engaño, mayor que la de un guerrero con el mismo Carisma. Presa sigue con 8 + FUE + competencia. Ponte detrás de una mesa y usa Ponerse a cubierto: queda cobertura de tres cuartos (+5), no media. En «12 · Lo que cualquiera puede intentar», cada fila dice si es regla base del Manual o de Ecos.'},
 {id:'conjuros315',titulo:'3.15 · Conjuros de PF2e, la lupa y Resonancia',pasos:'Recarga el mundo como DM y espera un minuto: aparece el compendio «Conjuros de PF2e (Ecos)» con carpetas por nivel, y «Listas de conjuros de PF2e (Ecos)» con el glosario. En la hoja de un mago, en el libro de conjuros, pulsa la lupa de Nivel 1: el buscador muestra conjuros de D&D y de PF2e de la lista de mago. Elige uno: si te quedan gratis, entra sin coste; si no, pide copiarlo por 50 po y 2 horas por nivel. Despierta el Verbe de una hoja: recibe la dote «Resonancia del Verbe». Con naturaleza Fuego, la CD de un conjuro de fuego sube 1 en la hoja y su ataque suma +1. Con naturaleza Agua, Curar heridas cura 1 PG más por dado.'},
];
export function anotarIncidencia(codigo){incidencias.push({codigo:String(codigo).replace(/[^a-z0-9:._-]/gi,'').slice(0,90),fecha:new Date().toISOString()});if(incidencias.length>30)incidencias.shift();}
export function diagnosticoMesa(){
 const mods=['ecos-frontera','plutonium','midi-qol','item-piles','itempilesdnd5e'].map(id=>{const m=game.modules.get(id);return {id,instalado:!!m,activo:!!m?.active,version:m?.version??null};});
 const avisos=[],core=String(game.version??game.release?.version??'desconocida'),sistema=game.system??{};
 if(!core.startsWith('13.'))avisos.push('Esta revisión apunta a Foundry 13; comprueba la compatibilidad de tu versión.');
 if(sistema.id!=='dnd5e')avisos.push('La integración requiere el sistema dnd5e.');
 if(sistema.version!=='5.2.5')avisos.push('La base de integración comprobada en código es dnd5e 5.2.5; tu combinación necesita las pruebas reales.');
 if(game.modules.get('plutonium')?.active&&!game.modules.get('plutonium')?.api?.importer?.pOpen)avisos.push('Plutonium no expone el importador esperado. Usa su botón nativo y registra la versión.');
 const api=game.modules.get(MOD)?.api;
 if(!api?.verbe?.datos?.())avisos.push('El catálogo del Verbe no está disponible: revisa Capa V y espera a que termine la carga.');
 if(!game.users?.activeGM)avisos.push('No hay GM principal conectado para propuestas y operaciones que requieren DM.');
 return {formato:1,fecha:new Date().toISOString(),core,sistema:{id:sistema.id??null,version:sistema.version??null},modulos:mods,
  ...(game.user.isGM?{pruebas:PRUEBAS_REALES.map(p=>({id:p.id,estado:(()=>{const x=game.journal?.find(j=>j.getFlag?.(MOD,'pruebasMesa'))?.getFlag(MOD,'resultadoPruebas')?.[p.id]?.estado;return ['pendiente','correcto','fallo','no-aplica'].includes(x)?x:'pendiente';})()}))}:{}),
  capacidades:{importador:!!game.modules.get('plutonium')?.api?.importer?.pOpen,midi:!!game.modules.get('midi-qol')?.active,verbe:!!api?.verbe?.datos?.(),resolucion:!!api?.resolucion},avisos,incidencias:[...incidencias],
  privacidad:'Informe técnico sin nombres de actores, secretos, diarios, tokens, rutas locales ni credenciales. No prueba que una sesión real haya pasado.'};
}
export async function cuadernoPruebas(){
 if(!game.user.isGM)return null;let j=game.journal?.find(x=>x.getFlag(MOD,'pruebasMesa'));
 const ownership={default:0,...Object.fromEntries(Array.from(game.users).filter(u=>!u.isGM).map(u=>[u.id,0]))};
 if(!j)j=await JournalEntry.create({name:'Ecos · Pruebas reales de mesa (DM)',ownership,flags:{[MOD]:{pruebasMesa:true}},pages:[{name:'Recorrido de validación 3.4',type:'text',text:{format:1,content:'<h1>Antes de la primera sesión</h1><p>Haz estas pruebas en un mundo o fichas de prueba con respaldo. El módulo no las marca como superadas por ejecutar pruebas de código.</p>'+PRUEBAS_REALES.map(p=>`<h2>${p.titulo}</h2><p>${p.pasos}</p>`).join('')}}]});
 await j.update({ownership},{diff:false,recursive:false});return j;
}
export async function registrarPrueba(id,estado,nota=''){
 if(!game.user.isGM||!PRUEBAS_REALES.some(p=>p.id===id)||!['pendiente','correcto','fallo','no-aplica'].includes(estado))return false;
 const j=await cuadernoPruebas(),datos=j.getFlag(MOD,'resultadoPruebas')??{};
 await j.setFlag(MOD,'resultadoPruebas',{...datos,[id]:{estado,nota:String(nota).slice(0,1000),fecha:new Date().toISOString(),por:game.user.id}});return true;
}
export function exportarDiagnostico(){const data=diagnosticoMesa();(foundry.utils.saveDataToFile??globalThis.saveDataToFile)(JSON.stringify(data,null,2),'application/json','Ecos-Diagnostico.json');return data;}
